void RobotFSM_PostObstacleCheck::evTick(RobotFSMContext& context)
{
    RobotContext& ctxt = context.getOwner();

    if (ctxt.isPostCheckPassed())
    {
        context.getState().Exit(context);
        context.clearState();
        try
        {
            ctxt.ctxt.logPostCheckToTraversing();
            ctxt.ctxt.setDriveModeForward();
            context.setState(RobotFSM::Traversing);
        }
        catch (...)
        {
            context.setState(RobotFSM::Traversing);
            throw;
        }
        context.getState().Entry(context);
    }
    else if (ctxt.isPostCheckFailed())

    {
        context.getState().Exit(context);
        context.clearState();
        try
        {
            ctxt.ctxt.reportErrorPostCheckFailed();
            ctxt.ctxt.stopAllMotors();
            context.setState(RobotFSM::SafeStop);
        }
        catch (...)
        {
            context.setState(RobotFSM::SafeStop);
            throw;
        }
        context.getState().Entry(context);
    }    else
    {
         RobotFSM_Default::evTick(context);
    }


}

